# cuts in bottom-right quarter after folds (top->bottom, then left->right)
# shapes encoded by (horizontal arm: 'top'/'bottom', vertical arm: 'left'/'right'); location in quarter
cuts=[(('top','right'),'inner'),(('bottom','left'),'corner')]
def flipLR(s): return (s[0],{'left':'right','right':'left'}[s[1]])
def flipUD(s): return ({'top':'bottom','bottom':'top'}[s[0]],s[1])
res={}
for s,loc in cuts:
    res[('BR',loc)]=s; res[('BL',loc)]=flipLR(s); res[('TR',loc)]=flipUD(s); res[('TL',loc)]=flipUD(flipLR(s))
C_opt={('TL','corner'):('top','right'),('TR','corner'):('top','left'),('BL','corner'):('bottom','right'),('BR','corner'):('bottom','left'),
       ('TL','inner'):('bottom','left'),('TR','inner'):('bottom','right'),('BL','inner'):('top','left'),('BR','inner'):('top','right')}
counts={'A':6,'B':6,'C':8,'D':6}
assert len(res)==counts['C'] and res==C_opt
for k in 'ABD': assert counts[k]!=len(res)

